const mount=document.querySelector('#idea-editor');
if(mount){
  const DB='ai-workflow-idea-deck',STORE='presentation',KEY='main';
  const defaultState={locked:false,cover:{title:'THE MACHINE LEAVES A TRACE',subtitle:'A project proposal about making AI visible as a material process.',titleColor:'#10110d',subtitleColor:'#10110d',titleBold:true,subtitleBold:false},sections:[{id:crypto.randomUUID(),layout:0,bg:'#cfff00',title:'THE WORKFLOW BECOMES THE SUBJECT',body:'Prompts, selections, errors, iterations and human intervention remain visible. The final work is not only an outcome—it is also a record of negotiation.',titleColor:'#10110d',bodyColor:'#10110d',titleBold:true,bodyBold:false,media:[]}]};
  let state,saveTimer,drag;
  const esc=v=>String(v??'').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));
  const openDB=()=>new Promise((resolve,reject)=>{const r=indexedDB.open(DB,1);r.onupgradeneeded=()=>r.result.createObjectStore(STORE);r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error)});
  const load=async()=>{try{const db=await openDB();return await new Promise((resolve,reject)=>{const r=db.transaction(STORE).objectStore(STORE).get(KEY);r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error)})}catch{return null}};
  const persist=async()=>{try{const db=await openDB();await new Promise((resolve,reject)=>{const r=db.transaction(STORE,'readwrite').objectStore(STORE).put(state,KEY);r.onsuccess=resolve;r.onerror=()=>reject(r.error)});toast('SAVED IN THIS BROWSER')}catch{toast('COULD NOT SAVE')}};
  const queueSave=()=>{clearTimeout(saveTimer);saveTimer=setTimeout(persist,260)};
  const textTools=(scope,key,color,bold)=>`<span class="text-tools"><label>COLOR <input type="color" data-action="color" data-scope="${scope}" data-key="${key}" value="${color}"></label><label><input type="checkbox" data-action="bold" data-scope="${scope}" data-key="${key}" ${bold?'checked':''}> BOLD</label></span>`;
  const editable=(tag,cls,scope,key,text,color,bold)=>`<div class="editable-line">${textTools(scope,key,color,bold)}<${tag} class="${cls}" data-edit="${key}" data-scope="${scope}" contenteditable="${state.locked?'false':'true'}" spellcheck="true" style="color:${color};font-weight:${bold?'900':'400'}">${esc(text)}</${tag}></div>`;
  const mediaHTML=(m,sectionId)=>{const url=URL.createObjectURL(m.file);return `<article class="media-card ${m.kind}" data-media="${m.id}" data-section="${sectionId}" style="--x:${m.x}%;--y:${m.y}%;--w:${m.w}%;--z:${m.z};--rotate:${m.rotate}deg"><button class="media-grip" type="button" aria-label="Move media">DRAG / MOVE</button><button class="media-remove" type="button" aria-label="Remove media">×</button><div class="media-content">${m.kind==='image'?`<img src="${url}" alt="${esc(m.name)}">`:`<video src="${url}" playsinline preload="metadata" ${state.locked?'controls':''} aria-label="${esc(m.name)}"></video>`}</div><button class="media-resize" type="button" aria-label="Resize media">↘</button></article>`};
  const sectionHTML=(s,i)=>`<section class="deck-section layout-${s.layout}" data-section="${s.id}" style="--section-bg:${s.bg}"><div class="section-kicker"><span>PART ${String(i+1).padStart(2,'0')} / IDEA FRAME</span><label class="section-bg-tool">BACKGROUND <input type="color" data-action="section-bg" value="${s.bg}"></label></div><div class="section-grid"><div class="section-copy">${editable('h2','section-title',s.id,'title',s.title,s.titleColor,s.titleBold)}${editable('p','section-body',s.id,'body',s.body,s.bodyColor,s.bodyBold)}</div><div class="media-stage" data-stage="${s.id}">${s.media.length?'':'<div class="media-empty">UPLOAD IMAGES OR VIDEOS<br>THEN DRAG + RESIZE</div>'}${s.media.map(m=>mediaHTML(m,s.id)).join('')}<div class="media-toolbar"><label class="upload-media">+ ADD VISUALS<input type="file" accept="image/*,video/*" multiple data-upload="${s.id}"></label></div></div></div></section>`;
  function render(){mount.innerHTML=`<div class="idea-shell ${state.locked?'locked':'editing'}"><div class="idea-editor-bar"><div><strong>${state.locked?'PRESENTATION MODE':'EDIT MODE'}</strong><small>${state.locked?'Layout locked · hover images · click videos':'Text, colour, position and size are editable'}</small></div><button class="mode-button" type="button" data-action="toggle-lock" aria-pressed="${state.locked}">${state.locked?'EDIT PRESENTATION':'FINISH + LOCK'}</button></div><header class="deck-cover"><div class="cover-fields">${editable('h1','cover-title','cover','title',state.cover.title,state.cover.titleColor,state.cover.titleBold)}${editable('p','cover-subtitle','cover','subtitle',state.cover.subtitle,state.cover.subtitleColor,state.cover.subtitleBold)}</div></header><div class="deck-sections">${state.sections.map(sectionHTML).join('')}</div><div class="deck-add-zone"><button class="add-section" type="button" data-action="add-section">+ ADD NEXT SECTION</button></div></div><div class="idea-toast" role="status"></div>`;bind();}
  function getSection(id){return state.sections.find(s=>s.id===id)}
  function toast(message){const el=mount.querySelector('.idea-toast');if(!el)return;el.textContent=message;el.classList.add('show');setTimeout(()=>el.classList.remove('show'),1500)}
  function updateText(el){const scope=el.dataset.scope,key=el.dataset.edit,value=el.innerText.trim();if(scope==='cover')state.cover[key]=value;else getSection(scope)[key]=value;queueSave()}
  function bind(){
    mount.querySelector('[data-action="toggle-lock"]').addEventListener('click',()=>{state.locked=!state.locked;persist();render();window.scrollTo({top:document.querySelector('.idea-deck').offsetTop,behavior:'smooth'})});
    mount.querySelector('[data-action="add-section"]')?.addEventListener('click',()=>{const n=state.sections.length;state.sections.push({id:crypto.randomUUID(),layout:Math.floor(Math.random()*3),bg:['#cfff00','#ff4a00','#fff7d6'][n%3],title:'NEW IDEA / NEW DIRECTION',body:'Click here to write the next part of your proposal.',titleColor:'#10110d',bodyColor:'#10110d',titleBold:true,bodyBold:false,media:[]});persist();render();setTimeout(()=>document.querySelector('.deck-section:last-of-type')?.scrollIntoView({behavior:'smooth'}),30)});
    mount.querySelectorAll('[contenteditable=true]').forEach(el=>{el.addEventListener('input',()=>updateText(el));el.addEventListener('blur',()=>updateText(el))});
    mount.querySelectorAll('[data-action="color"]').forEach(el=>el.addEventListener('input',()=>{const {scope,key}=el.dataset,target=scope==='cover'?state.cover:getSection(scope);target[`${key}Color`]=el.value;el.closest('.editable-line').querySelector('[data-edit]').style.color=el.value;queueSave()}));
    mount.querySelectorAll('[data-action="bold"]').forEach(el=>el.addEventListener('change',()=>{const {scope,key}=el.dataset,target=scope==='cover'?state.cover:getSection(scope);target[`${key}Bold`]=el.checked;el.closest('.editable-line').querySelector('[data-edit]').style.fontWeight=el.checked?'900':'400';queueSave()}));
    mount.querySelectorAll('[data-action="section-bg"]').forEach(el=>el.addEventListener('input',()=>{const sec=el.closest('.deck-section'),s=getSection(sec.dataset.section);s.bg=el.value;sec.style.setProperty('--section-bg',el.value);queueSave()}));
    mount.querySelectorAll('[data-upload]').forEach(input=>input.addEventListener('change',async()=>{const s=getSection(input.dataset.upload),base=s.media.length;for(const [i,file] of [...input.files].entries()){const kind=file.type.startsWith('video/')?'video':file.type.startsWith('image/')?'image':null;if(!kind)continue;s.media.push({id:crypto.randomUUID(),kind,name:file.name,file,x:6+((base+i)*17)%48,y:8+((base+i)*19)%52,w:kind==='video'?52:38,z:base+i+2,rotate:[-2,1.5,-.5][(base+i)%3]})}await persist();render()}));
    mount.querySelectorAll('.media-remove').forEach(btn=>btn.addEventListener('click',()=>{const card=btn.closest('.media-card'),s=getSection(card.dataset.section);s.media=s.media.filter(m=>m.id!==card.dataset.media);persist();render()}));
    mount.querySelectorAll('.media-grip').forEach(grip=>grip.addEventListener('pointerdown',startMove));
    mount.querySelectorAll('.media-resize').forEach(handle=>handle.addEventListener('pointerdown',startResize));
    mount.querySelectorAll('.media-card.video video').forEach(video=>video.addEventListener('click',async()=>{if(!state.locked)return;try{await video.requestFullscreen();await video.play()}catch{toast('FULLSCREEN IS NOT AVAILABLE')}}));
  }
  function startMove(e){if(state.locked)return;e.preventDefault();const card=e.currentTarget.closest('.media-card'),stage=card.parentElement,s=getSection(card.dataset.section),m=s.media.find(v=>v.id===card.dataset.media),r=stage.getBoundingClientRect();drag={type:'move',pointer:e.pointerId,card,stage,m,r,startX:e.clientX,startY:e.clientY,x:m.x,y:m.y};e.currentTarget.setPointerCapture(e.pointerId);e.currentTarget.addEventListener('pointermove',onDrag);e.currentTarget.addEventListener('pointerup',endDrag,{once:true})}
  function startResize(e){if(state.locked)return;e.preventDefault();const card=e.currentTarget.closest('.media-card'),stage=card.parentElement,s=getSection(card.dataset.section),m=s.media.find(v=>v.id===card.dataset.media),r=stage.getBoundingClientRect();drag={type:'resize',pointer:e.pointerId,card,stage,m,r,startX:e.clientX,w:m.w};e.currentTarget.setPointerCapture(e.pointerId);e.currentTarget.addEventListener('pointermove',onDrag);e.currentTarget.addEventListener('pointerup',endDrag,{once:true})}
  function onDrag(e){if(!drag||e.pointerId!==drag.pointer)return;if(drag.type==='move'){drag.m.x=Math.max(0,Math.min(92,drag.x+(e.clientX-drag.startX)/drag.r.width*100));drag.m.y=Math.max(0,Math.min(86,drag.y+(e.clientY-drag.startY)/drag.r.height*100));drag.card.style.setProperty('--x',`${drag.m.x}%`);drag.card.style.setProperty('--y',`${drag.m.y}%`)}else{drag.m.w=Math.max(20,Math.min(88,drag.w+(e.clientX-drag.startX)/drag.r.width*100));drag.card.style.setProperty('--w',`${drag.m.w}%`)}}
  function endDrag(e){e.currentTarget.removeEventListener('pointermove',onDrag);drag=null;queueSave()}
  state=await load()||defaultState;render();
}
